begin;
create function pg_temp.pa_assert(ok boolean,label text) returns text language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;return label;end $$;
create function pg_temp.pa_denied(stmt text,label text,expected text default null) returns text language plpgsql as $$begin begin execute stmt;exception when others then if expected is not null and sqlstate<>expected then raise exception 'Wrong error % for %',sqlstate,label;end if;return label;end;raise exception 'Unexpected success: %',label;end $$;
insert into auth.users(id,email)select ('da100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'personal-autonomy-qa-'||n||'@example.test' from generate_series(1,6)n;
insert into public.patient_profiles(id,auth_user_id,email,display_name)select ('da200000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('da100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'personal-autonomy-qa-'||n||'@example.test','Persona neutral autonomía '||n from generate_series(1,2)n;
insert into public.admin_users(user_id,role,is_active)values('da100000-0000-4000-8000-000000000003','recovery_coach',true),('da100000-0000-4000-8000-000000000004','recovery_coach',true),('da100000-0000-4000-8000-000000000005','superadmin',true),('da100000-0000-4000-8000-000000000006','editor',true);
insert into public.care_assignments(patient_id,professional_id,specialty,starts_at,created_by)select 'da200000-0000-4000-8000-000000000001',('da100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'recovery',now()-interval '1 day','da100000-0000-4000-8000-000000000005' from generate_series(3,4)n;
create function pg_temp.pa_payload() returns jsonb language sql security definer set search_path='' as $$
select jsonb_build_object('evaluation_date',(now() at time zone 'America/Santiago')::date,'coach_id','da100000-0000-4000-8000-000000000003','meeting_day','Martes QA','review_frequency','Cada dos semanas QA','next_review',null,'additional_notes','Texto neutral QA',
'answers',(select jsonb_object_agg(it->>'id',jsonb_build_object('value',case when ar->>'key'<='F' then '0'::jsonb else '"A veces"'::jsonb end,'context','Ejemplo neutral QA','missing_reason',''))from private.care_pa_catalogs c cross join lateral jsonb_array_elements(c.definition->'areas')ar cross join lateral jsonb_array_elements(ar->'items')it where c.id='da000000-0000-4000-8000-000000000001'),
'open_answers',(select jsonb_object_agg(q->>'id','Respuesta neutral QA')from private.care_pa_catalogs c cross join lateral jsonb_array_elements(c.definition->'questions')q where c.id='da000000-0000-4000-8000-000000000001' and q->>'section'<>'learning'))$$;
create function pg_temp.pa_save(ver integer,mode text default 'self') returns jsonb language sql as $$select jsonb_build_object('id','da300000-0000-4000-8000-000000000001','catalog_id','da000000-0000-4000-8000-000000000001','baseline_id',null,'version',ver,'mode',mode,'patient_present',mode='assisted','confirm',true,'reason','Registro neutral QA','payload',pg_temp.pa_payload())$$;
create function pg_temp.pa_proposal() returns jsonb language sql as $$select jsonb_build_object('id','da400000-0000-4000-8000-000000000001','assessment_id','da300000-0000-4000-8000-000000000001','assessment_revision',2,'area','A','item_id','A1','description','Tarea neutral autonomía QA','responsible_kind','patient','responsible_id',null,'due_at',now()+interval '2 days','frequency','Semanal QA','review_at',now()+interval '3 days','verification','Revisar ejemplo neutral QA','difficulty','Dificultad neutral QA','contingency','Pedir apoyo neutral QA','existing_commitment_id',null)$$;
create temporary table pa_fixture(k text primary key,p jsonb);grant select,insert,update on pa_fixture to authenticated;
insert into pa_fixture values('proposal',pg_temp.pa_proposal());
insert into private.care_pa_catalogs(id,document_version,definition)select 'da000000-0000-4000-8000-000000000002','QA incompatible',definition||jsonb_build_object('id','da000000-0000-4000-8000-000000000002','document_version','QA incompatible')from private.care_pa_catalogs where id='da000000-0000-4000-8000-000000000001';
insert into public.care_commitments(id,patient_id,title,due_at,visibility,origin,created_by)values('da800000-0000-4000-8000-000000000001','da200000-0000-4000-8000-000000000001','Compromiso compartido previo QA','2026-10-25T12:00:00Z','patient','self','da100000-0000-4000-8000-000000000001');
select pg_temp.pa_assert((select count(*)=1 from private.care_pa_catalogs where document_version='1.0-transcription'),'Independent catalog seeded once');
select pg_temp.pa_assert((select jsonb_array_length(definition->'areas')=8 from private.care_pa_catalogs where document_version='1.0-transcription'),'Eight exact areas');
select pg_temp.pa_assert((select count(*)=41 from private.care_pa_catalogs c cross join lateral jsonb_array_elements(c.definition->'areas')a cross join lateral jsonb_array_elements(a->'items')i where c.document_version='1.0-transcription'),'41 transcribed items');
select pg_temp.pa_denied($$update private.care_pa_catalogs set document_version='changed'$$,'Catalog content immutable');
select pg_temp.pa_assert((select governance_state='proposal' and approved_by is null and not criteria_enabled from public.care_recovery_rubrics where id='c0000000-0000-4000-8000-000000000001'),'Previous rubric remains pending, criteria off');
set local role anon;
select pg_temp.pa_denied($$select public.care_pa_context('da200000-0000-4000-8000-000000000001')$$,'Anon cannot read','42501');
select pg_temp.pa_denied($$select public.care_pa_write('da200000-0000-4000-8000-000000000001','draft','{}')$$,'Anon cannot write','42501');
reset role;set local role authenticated;
select set_config('request.jwt.claim.sub','da100000-0000-4000-8000-000000000001',true);
select pg_temp.pa_denied($$select * from private.care_pa_versions$$,'No direct private data access','42501');
select pg_temp.pa_denied($$select public.care_pa_context('da200000-0000-4000-8000-000000000002')$$,'Patient isolation read','42501');
select pg_temp.pa_denied($$select public.care_pa_write('da200000-0000-4000-8000-000000000002','draft',pg_temp.pa_save(0))$$,'Patient isolation write','42501');
select public.care_pa_write('da200000-0000-4000-8000-000000000001','draft',pg_temp.pa_save(0)||jsonb_build_object('payload',pg_temp.pa_payload()||jsonb_build_object('answers',jsonb_build_object('A1',jsonb_build_object('value',0,'context','','missing_reason',''),'A2',jsonb_build_object('value',null,'context','','missing_reason','Sin información QA')))));
select pg_temp.pa_assert(public.care_pa_context('da200000-0000-4000-8000-000000000001')->'assessments'->0->'payload'->'answers'->'A1'->'value'='0'::jsonb,'Zero is a valid answer');
select pg_temp.pa_assert(public.care_pa_context('da200000-0000-4000-8000-000000000001')->'assessments'->0->'payload'->'answers'->'A2'->'value'='null'::jsonb,'Missing remains distinct from zero');
select pg_temp.pa_denied($$select public.care_pa_write('da200000-0000-4000-8000-000000000001','submit',pg_temp.pa_save(1)||jsonb_build_object('payload',pg_temp.pa_payload()||jsonb_build_object('answers','{}'::jsonb)))$$,'Submit requires answered items or explicit missingness');
select pg_temp.pa_denied($$select public.care_pa_write('da200000-0000-4000-8000-000000000001','submit',pg_temp.pa_save(1)||jsonb_build_object('payload',jsonb_set(pg_temp.pa_payload(),'{answers,G1,value}','1'::jsonb)))$$,'Categorical area rejects numeric coding');
select pg_temp.pa_denied($$select public.care_pa_write('da200000-0000-4000-8000-000000000001','submit',pg_temp.pa_save(1)||jsonb_build_object('payload',jsonb_set(pg_temp.pa_payload(),'{answers,A1,value}','"Sí"'::jsonb)))$$,'Ordinal area rejects yes/no');
select public.care_pa_write('da200000-0000-4000-8000-000000000001','submit',pg_temp.pa_save(1));
select pg_temp.pa_assert(public.care_pa_context('da200000-0000-4000-8000-000000000001')->'assessments'->0->'payload'->'answers'->'G1'->>'value'='A veces','Categorical answer preserved exactly');
select pg_temp.pa_denied($$select public.care_pa_write('da200000-0000-4000-8000-000000000001','submit',pg_temp.pa_save(1))$$,'Concurrent edit rejected','40001');
select public.care_pa_write('da200000-0000-4000-8000-000000000001','submit',pg_temp.pa_save(0)||jsonb_build_object('id','da300000-0000-4000-8000-000000000002','baseline_id','da300000-0000-4000-8000-000000000001'));
select pg_temp.pa_assert(jsonb_array_length(public.care_pa_context('da200000-0000-4000-8000-000000000001')->'assessments')=3,'Reevaluation keeps initial and draft history');
select pg_temp.pa_denied($$select public.care_pa_write('da200000-0000-4000-8000-000000000001','submit',pg_temp.pa_save(0)||jsonb_build_object('id','da300000-0000-4000-8000-000000000003','catalog_id','da000000-0000-4000-8000-000000000002','baseline_id','da300000-0000-4000-8000-000000000001'))$$,'Different instrument versions cannot share baseline');
select pg_temp.pa_denied($$select public.care_pa_write('da200000-0000-4000-8000-000000000001','submit',pg_temp.pa_save(0)||jsonb_build_object('id','da300000-0000-4000-8000-000000000003','baseline_id','da300000-0000-4000-8000-000000000002'))$$,'Reevaluation cannot replace baseline with another reevaluation');
select set_config('request.jwt.claim.sub','da100000-0000-4000-8000-000000000003',true);
select pg_temp.pa_denied($$select public.care_pa_context('da200000-0000-4000-8000-000000000002')$$,'Unassigned coach isolation','42501');
select pg_temp.pa_denied($$select public.care_pa_write('da200000-0000-4000-8000-000000000001','draft',pg_temp.pa_save(2))$$,'Coach cannot silently replace patient response');
select public.care_pa_write('da200000-0000-4000-8000-000000000001','draft',pg_temp.pa_save(2,'assisted'));
select pg_temp.pa_assert(public.care_pa_context('da200000-0000-4000-8000-000000000001')->'assessments'->0->>'entered_by'='da100000-0000-4000-8000-000000000003','Assisted loading records actual actor');
select pg_temp.pa_assert(public.care_pa_context('da200000-0000-4000-8000-000000000001')->'assessments'->0->>'respondent_patient_id'='da200000-0000-4000-8000-000000000001','Respondent remains patient');
select public.care_pa_write('da200000-0000-4000-8000-000000000001','propose',(select p from pa_fixture where k='proposal'));
select public.care_pa_write('da200000-0000-4000-8000-000000000001','propose',(select p from pa_fixture where k='proposal'));
select pg_temp.pa_assert(jsonb_array_length(public.care_pa_context('da200000-0000-4000-8000-000000000001')->'proposals')=1,'Proposal retry idempotent');
select pg_temp.pa_assert(public.care_pa_context('da200000-0000-4000-8000-000000000001')->'proposals'->0->>'origin'='coach','Coach origin preserved');
select pg_temp.pa_assert(public.care_pa_context('da200000-0000-4000-8000-000000000001')->'proposals'->0->>'commitment_id' is null,'Proposed task not automatically accepted');
select public.care_pa_write('da200000-0000-4000-8000-000000000001','accept',jsonb_build_object('id',gen_random_uuid(),'proposal_id','da400000-0000-4000-8000-000000000001','confirm',true));
select pg_temp.pa_assert(public.care_pa_context('da200000-0000-4000-8000-000000000001')->'proposals'->0->>'commitment_id' is null,'Coach acceptance does not impersonate patient');
select set_config('request.jwt.claim.sub','da100000-0000-4000-8000-000000000001',true);
select public.care_pa_write('da200000-0000-4000-8000-000000000001','accept',jsonb_build_object('id',gen_random_uuid(),'proposal_id','da400000-0000-4000-8000-000000000001','confirm',true));
select public.care_pa_write('da200000-0000-4000-8000-000000000001','accept',jsonb_build_object('id',gen_random_uuid(),'proposal_id','da400000-0000-4000-8000-000000000001','confirm',true));
select pg_temp.pa_assert((select count(*)=1 from public.care_commitments where patient_id='da200000-0000-4000-8000-000000000001' and source_personal_proposal_id is not null),'One real linked commitment after both acceptances and retries');
insert into pa_fixture values('review',jsonb_build_object('id','da500000-0000-4000-8000-000000000001','proposal_id','da400000-0000-4000-8000-000000000001','supersedes',null,'review_date','2026-10-17','period_start','2026-10-01','period_end','2026-10-17','outcome','Parcialmente cumplida','result','Avance parcial neutral QA','evidence','Ejemplo neutral QA','support','Apoyo neutral QA','next_step','Ajuste neutral QA','learning',jsonb_build_object('learning1','Avance pequeño neutral QA'),'shared',true,'reason','Revisión neutral QA'));
select public.care_pa_write('da200000-0000-4000-8000-000000000001','review',(select p from pa_fixture where k='review'));
select public.care_pa_write('da200000-0000-4000-8000-000000000001','review',(select p from pa_fixture where k='review'));
select pg_temp.pa_assert(public.care_pa_context('da200000-0000-4000-8000-000000000001')->'reviews'->0->>'outcome'='Parcialmente cumplida','Partial outcome exact, retry once');
select public.care_pa_write('da200000-0000-4000-8000-000000000001','review',(select p||jsonb_build_object('id','da500000-0000-4000-8000-000000000002','supersedes','da500000-0000-4000-8000-000000000001','outcome','Reformulada / pausada')from pa_fixture where k='review'));
select public.care_pa_write('da200000-0000-4000-8000-000000000001','review',(select p||jsonb_build_object('id','da500000-0000-4000-8000-000000000003','outcome','No evaluable')from pa_fixture where k='review'));
select pg_temp.pa_assert(jsonb_array_length(public.care_pa_context('da200000-0000-4000-8000-000000000001')->'reviews')=3,'Correction preserves previous outcomes and evidence');
select pg_temp.pa_assert((select bool_and(status='pending' and confirmation is null)from public.care_commitments where patient_id='da200000-0000-4000-8000-000000000001'),'Partial paused and not evaluable never become failures or verified success');
select pg_temp.pa_denied($$select public.care_pa_write('da200000-0000-4000-8000-000000000001','review',(select p||jsonb_build_object('id',gen_random_uuid(),'shared',false)from pa_fixture where k='review'))$$,'Patient cannot hide shared review');
select public.care_pa_write('da200000-0000-4000-8000-000000000001','attest',jsonb_build_object('id','da600000-0000-4000-8000-000000000001','assessment_id','da300000-0000-4000-8000-000000000001','revision',2,'state','differences','note','Diferencia neutral QA','confirm',true));
