select public.care_pa_write('da200000-0000-4000-8000-000000000001','propose',(select p||jsonb_build_object('id','da400000-0000-4000-8000-000000000002','due_at',null,'frequency','Quincenal sin plazo QA')from pa_fixture where k='proposal'));
select pg_temp.pa_assert(jsonb_array_length(public.care_pa_context('da200000-0000-4000-8000-000000000001')->'attestations'->0->'agreement_snapshot')=1,'Later proposals cannot change an earlier conversation snapshot');
select public.care_pa_write('da200000-0000-4000-8000-000000000001','accept',jsonb_build_object('id',gen_random_uuid(),'proposal_id','da400000-0000-4000-8000-000000000002','confirm',true));
