select pg_temp.pa_assert((select due_at is null and review_at is not null from public.care_commitments where source_personal_proposal_id='da400000-0000-4000-8000-000000000002'),'Frequency-only agreement keeps review date without invented deadline');
select pg_temp.pa_assert((select source_personal_proposal_id='da400000-0000-4000-8000-000000000003' from public.care_commitments where id='da800000-0000-4000-8000-000000000001'),'Existing task has one explicit source link');
select public.care_pa_write('da200000-0000-4000-8000-000000000001','attest',jsonb_build_object('id','da600000-0000-4000-8000-000000000002','assessment_id','da300000-0000-4000-8000-000000000001','revision',2,'state','pending','note','Pendiente neutral QA','confirm',true));
select pg_temp.pa_assert(exists(select 1 from jsonb_array_elements(public.care_pa_context('da200000-0000-4000-8000-000000000001')->'attestations')t where t->>'id'='da600000-0000-4000-8000-000000000002' and t->>'party'='coach' and t->>'actor_id'='da100000-0000-4000-8000-000000000003'),'Coach cannot sign patient attestation');
select public.care_pa_write('da200000-0000-4000-8000-000000000001','observe',jsonb_build_object('id','da700000-0000-4000-8000-000000000001','assessment_id','da300000-0000-4000-8000-000000000001','revision',2,'body','Observación privada neutral QA','shared',false));
select public.care_pa_write('da200000-0000-4000-8000-000000000001','observe',jsonb_build_object('id','da700000-0000-4000-8000-000000000002','assessment_id','da300000-0000-4000-8000-000000000001','revision',2,'body','Observación compartida neutral QA','shared',true));
