select pg_temp.pa_denied($$select public.care_pa_write('da200000-0000-4000-8000-000000000001','review',(select p||jsonb_build_object('id',gen_random_uuid(),'supersedes','da500000-0000-4000-8000-000000000003')from pa_fixture where k='review'))$$,'Other actor cannot correct patient review','42501');
select set_config('request.jwt.claim.sub','da100000-0000-4000-8000-000000000005',true);
select pg_temp.pa_denied($$update public.care_commitments set title='Cambio silencioso QA' where source_personal_proposal_id='da400000-0000-4000-8000-000000000001'$$,'Accepted goal cannot be silently rewritten by generic planning');
