update public.care_assignments set ends_at=now() where professional_id='da100000-0000-4000-8000-000000000003';
set local role authenticated;select set_config('request.jwt.claim.sub','da100000-0000-4000-8000-000000000003',true);
select pg_temp.pa_denied($$select public.care_pa_context('da200000-0000-4000-8000-000000000001')$$,'Assignment revocation effective immediately','42501');
