select set_config('request.jwt.claim.sub','da100000-0000-4000-8000-000000000005',true);
select pg_temp.pa_assert((select count(*)=2 from private.care_inform_sources(array['da200000-0000-4000-8000-000000000001'::uuid],'2026-01-01','2027-01-01',now()) where metric='personal_autonomy_self'),'Report includes submitted self-report revisions, excludes drafts');
select pg_temp.pa_assert((select count(*)=2 from private.care_inform_sources(array['da200000-0000-4000-8000-000000000001'::uuid],'2026-01-01','2027-01-01',now()) where metric='personal_autonomy_review' and category in ('Reformulada / pausada','No evaluable')),'Report keeps current exact review categories');
select pg_temp.pa_assert((select count(*)=1 from private.care_inform_sources(array['da200000-0000-4000-8000-000000000001'::uuid],'2026-01-01','2027-01-01',now()) where metric='personal_autonomy_coach'),'Reserved observations excluded from report even for Direction');
select pg_temp.pa_assert((select count(*)=0 from private.care_inform_sources(array['da200000-0000-4000-8000-000000000001'::uuid],'2026-01-01','2027-01-01',now()-interval '1 day') where metric like 'personal_autonomy_%'),'Report cutoff excludes later corrections and data');
select pg_temp.pa_denied($$update private.care_pa_versions set reason='changed'$$,'Assessment history immutable');
select pg_temp.pa_assert(not has_function_privilege('anon','public.care_pa_context(uuid)','execute') and not has_function_privilege('service_role','public.care_pa_write(uuid,text,jsonb)','execute'),'No anonymous or service RPC privilege side effect');
select pg_temp.pa_assert((select bool_and(relrowsecurity)from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname like 'care_pa_%' and c.relkind='r'),'Every personal-autonomy table has RLS');
select pg_temp.pa_assert(not exists(select 1 from information_schema.columns where table_schema='private' and table_name='care_audit' and column_name in ('payload','body','metadata','evidence')),'Audit excludes responses and evidence');
